                    An action is actually a composition of the following fundamental ROS entities
                    */
                    rosgraph_msgs.msg.Service send_goal;
                    rosgraph_msgs.msg.Service get_result;
                    rosgraph_msgs.msg.Service cancel_goal;
                    rosgraph_msgs.msg.Topic feedback;
                    rosgraph_msgs.msg.Topic status;
                }

                public class Clock {
                    /**
                    This message communicates the current time.
                    For more information, see https://design.ros2.org/articles/clock_and_time.html.
                    */
                    DateTime clock; // was builtin_interfaces/Time (int32 sec + uint32 nanosec); ns resolution dropped
                }

                public class Graph {
                    /**
                    Represents a ROS node graph, which is only a collection of nodes
                    */
                    rosgraph_msgs.msg.Node[,,] nodes;
                }

                /**
                Represent a type of a ROS Graph Interface
                */
