                    /**
                    Fully qualified node name (FQN)
                    */
                    string name;
                    /**
                    Parameter specifications for the node
                    */
                    rcl_interfaces.msg.ParameterDescriptor[,,] parameters;
                    /**
                    Current values of the node's parameters
                    NOTE:
                    parameter_values[] must be empty, or the same size as parameters[]
                    When set, parameter_values[] match 1:1 with the same index in parameters[]
                    */
                    rcl_interfaces.msg.ParameterValue[,,] parameter_values;
                    /**
                    Communications endpoints - Topics, Services, and Actions
                    */
                    rosgraph_msgs.msg.Topic[,,] publishers;
                    rosgraph_msgs.msg.Topic[,,] subscriptions;
                    rosgraph_msgs.msg.Service[,,] service_clients;
                    rosgraph_msgs.msg.Service[,,] service_servers;
                    rosgraph_msgs.msg.Action[,,] action_clients;
                    rosgraph_msgs.msg.Action[,,] action_servers;
                }

                /**
                Message-based representation of ROS 2 Quality of Service settings
                Default values are kept in sync with RMW by integration test
                Note that SYSTEM_DEFAULT and BEST_AVAILABLE values cannot be an observed value,
                because they resolve concretely at runtime.
                They are included here for completeness to match the data structures in RMW
                */
                public class QoSProfile {
                    /**
                    Depth of the message queue (only meaningful when history==KEEP_LAST)
                    */
                    // physics: a depth has a floor at 0 and no ceiling, and stays small in practice → consider [A]
                    uint depth;
                    /**
                    Deadline between messages (0 for no deadline)
                    */
                    ROS_Duration deadline; // was builtin_interfaces/Duration; see the ROS_Duration alias
                    /**
                    Lifespan of each message (0 for infinite)
                    */
                    ROS_Duration lifespan; // was builtin_interfaces/Duration; see the ROS_Duration alias
                    /**
                    History policy
                    */
                    const byte HISTORY_SYSTEM_DEFAULT = 0;
                    const byte HISTORY_KEEP_LAST = 1;
                    const byte HISTORY_KEEP_ALL = 2;
                    const byte HISTORY_UNKNOWN = 3;
                    byte history;
                    /**
                    Reliability policy
                    */
                    const byte RELIABILITY_SYSTEM_DEFAULT = 0;
                    const byte RELIABILITY_RELIABLE = 1;
                    const byte RELIABILITY_BEST_EFFORT = 2;
                    const byte RELIABILITY_UNKNOWN = 3;
                    const byte RELIABILITY_BEST_AVAILABLE = 4;
                    byte reliability;
                    /**
                    Durability policy
                    */
                    const byte DURABILITY_SYSTEM_DEFAULT = 0;
                    const byte DURABILITY_TRANSIENT_LOCAL = 1;
                    const byte DURABILITY_VOLATILE = 2;
                    const byte DURABILITY_UNKNOWN = 3;
                    const byte DURABILITY_BEST_AVAILABLE = 4;
                    byte durability;
                    /**
                    Liveliness policy
                    */
                    const byte LIVELINESS_SYSTEM_DEFAULT = 0;
                    const byte LIVELINESS_AUTOMATIC = 1;
                    const byte LIVELINESS_MANUAL_BY_TOPIC = 3;
                    const byte LIVELINESS_UNKNOWN = 4;
                    const byte LIVELINESS_BEST_AVAILABLE = 5;
                    byte liveliness;
                    /**
                    Lease duration for liveliness (0 for infinite)
                    */
                    ROS_Duration liveliness_lease_duration; // was builtin_interfaces/Duration; see the ROS_Duration alias
                }

                /**
                Describes a single Service endpoint, which may be a Server or Client
                */
                public class Service {
                    /**
                    Fully qualified name of the Service
                    */
                    string name;
                    /**
                    Type and actual QoS of the request publisher (Client) or subscription (Server)
                    */
                    rosgraph_msgs.msg.InterfaceType request_type;
                    rosgraph_msgs.msg.QoSProfile request_qos;
                    /**
                    Type and actual QoS of the request subscription (Client) or publisher (Server)
                    */
                    rosgraph_msgs.msg.InterfaceType response_type;
                    rosgraph_msgs.msg.QoSProfile response_qos;
                }

                /**
                Describes a single topic endpoint, which may be a Publisher or Subscription
                */
                public class Topic {
                    /**
                    Fully qualified name of the topic
                    */
                    string name;
                    /**
                    Type of the topic
                    */
                    rosgraph_msgs.msg.InterfaceType Type;
                    /**
                    Observed QoS of the endpoint
                    */
                    rosgraph_msgs.msg.QoSProfile qos;
                }

                public class TypeHash {
                    /**
                    RIHS spec version
                    */
                    [Default("1")] byte version;
                    /**
                    ROSIDL_TYPE_HASH_SIZE == 32
                    */
                    [D(32)] byte[] value;
                }
            }
        }

