                    const byte FIELD_TYPE_INT8_ARRAY = 50;
                    const byte FIELD_TYPE_UINT8_ARRAY = 51;
                    const byte FIELD_TYPE_INT16_ARRAY = 52;
                    const byte FIELD_TYPE_UINT16_ARRAY = 53;
