                (GetInteractiveMarkers.srv)
                */
                public class GetInteractiveMarkers_Request {
                }

                /**
                (GetInteractiveMarkers.srv)
                */
                public class GetInteractiveMarkers_Response {
                    /**
                    Sequence number.
                    Set to the sequence number of the latest update message
                    at the time the server received the request.
                    Clients use this to detect if any updates were missed.
                    */
                    // physics: a sequence_number has a floor at 0 and no ceiling, and stays small in practice → consider [A]
                    ulong sequence_number;
                    /**
                    All interactive markers provided by the server.
                    */
                    visualization_msgs.msg.InteractiveMarker[,,] markers;
                }
            }
        }

        // builtin_interfaces/Duration is an elapsed time, which AdHoc models natively: a `: Duration` alias
        // is bit-sized from the range below instead of shipping the two raw ROS fields (int32 sec + uint32 nanosec).
        // DROPPED: ROS allows a NEGATIVE duration (sec < 0); AdHoc's Duration is non-negative elapsed time.
        // DROPPED: nanosecond resolution - AdHoc normalises time to milliseconds and clamps precision at 1 ms.
        // Refine per use: a timeout that is always under a minute wants max => 60_000, not the ROS int32 ceiling.
        public class ROS_Duration : Duration {
            public long     max       => 2_147_483_647_000; // int32.MaxValue seconds, in 1 ms steps
            public TimeSpan precision => TimeSpan.FromMilliseconds(1);
        }

        // ═════════════════════════ topology ═════════════════════════

        // ROS 2 has no fixed topology: any node may publish any topic, call any service or act on any action.
        // The demo pairs a Client (calls services, sends action goals) with a Server (answers them);
        // topics flow in both directions.

        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct Client : Host { }

        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct Server : Host { }

        interface Communication : Connects<Client, Server> {
            // Topics: every *.msg pack of every package, selected by the `.msg.` container in its full name;
            // either side may publish, the FSM never transitions.
            [_____lr_____<@ros2_interfaces>(KeepName: @"\.msg\.")]
            struct Topics { }

            // Services: request from the Client, response from the Server (RPC shorthand, one transient actor per call).
            (L____________, action_msgs.srv.CancelGoal_Response) action_msgs_CancelGoal(action_msgs.srv.CancelGoal_Request req);
            (L____________, composition_interfaces.srv.ListNodes_Response) composition_interfaces_ListNodes(composition_interfaces.srv.ListNodes_Request req);
            (L____________, composition_interfaces.srv.LoadNode_Response) composition_interfaces_LoadNode(composition_interfaces.srv.LoadNode_Request req);
            (L____________, composition_interfaces.srv.UnloadNode_Response) composition_interfaces_UnloadNode(composition_interfaces.srv.UnloadNode_Request req);
            (L____________, diagnostic_msgs.srv.AddDiagnostics_Response) diagnostic_msgs_AddDiagnostics(diagnostic_msgs.srv.AddDiagnostics_Request req);
            (L____________, diagnostic_msgs.srv.SelfTest_Response) diagnostic_msgs_SelfTest(diagnostic_msgs.srv.SelfTest_Request req);
            (L____________, example_interfaces.srv.AddTwoInts_Response) example_interfaces_AddTwoInts(example_interfaces.srv.AddTwoInts_Request req);
            (L____________, example_interfaces.srv.SetBool_Response) example_interfaces_SetBool(example_interfaces.srv.SetBool_Request req);
            (L____________, example_interfaces.srv.Trigger_Response) example_interfaces_Trigger(example_interfaces.srv.Trigger_Request req);
            (L____________, lifecycle_msgs.srv.ChangeState_Response) lifecycle_msgs_ChangeState(lifecycle_msgs.srv.ChangeState_Request req);
            (L____________, lifecycle_msgs.srv.GetAvailableStates_Response) lifecycle_msgs_GetAvailableStates(lifecycle_msgs.srv.GetAvailableStates_Request req);
            (L____________, lifecycle_msgs.srv.GetAvailableTransitions_Response) lifecycle_msgs_GetAvailableTransitions(lifecycle_msgs.srv.GetAvailableTransitions_Request req);
            (L____________, lifecycle_msgs.srv.GetState_Response) lifecycle_msgs_GetState(lifecycle_msgs.srv.GetState_Request req);
            (L____________, nav_msgs.srv.GetMap_Response) nav_msgs_GetMap(nav_msgs.srv.GetMap_Request req);
            (L____________, nav_msgs.srv.GetPlan_Response) nav_msgs_GetPlan(nav_msgs.srv.GetPlan_Request req);
            (L____________, nav_msgs.srv.LoadMap_Response) nav_msgs_LoadMap(nav_msgs.srv.LoadMap_Request req);
            (L____________, nav_msgs.srv.SetMap_Response) nav_msgs_SetMap(nav_msgs.srv.SetMap_Request req);
            (L____________, rcl_interfaces.srv.DescribeParameters_Response) rcl_interfaces_DescribeParameters(rcl_interfaces.srv.DescribeParameters_Request req);
            (L____________, rcl_interfaces.srv.GetLoggerLevels_Response) rcl_interfaces_GetLoggerLevels(rcl_interfaces.srv.GetLoggerLevels_Request req);
            (L____________, rcl_interfaces.srv.GetParameterTypes_Response) rcl_interfaces_GetParameterTypes(rcl_interfaces.srv.GetParameterTypes_Request req);
            (L____________, rcl_interfaces.srv.GetParameters_Response) rcl_interfaces_GetParameters(rcl_interfaces.srv.GetParameters_Request req);
            (L____________, rcl_interfaces.srv.ListParameters_Response) rcl_interfaces_ListParameters(rcl_interfaces.srv.ListParameters_Request req);
            (L____________, rcl_interfaces.srv.SetLoggerLevels_Response) rcl_interfaces_SetLoggerLevels(rcl_interfaces.srv.SetLoggerLevels_Request req);
            (L____________, rcl_interfaces.srv.SetParameters_Response) rcl_interfaces_SetParameters(rcl_interfaces.srv.SetParameters_Request req);
            (L____________, rcl_interfaces.srv.SetParametersAtomically_Response) rcl_interfaces_SetParametersAtomically(rcl_interfaces.srv.SetParametersAtomically_Request req);
            (L____________, sensor_msgs.srv.SetCameraInfo_Response) sensor_msgs_SetCameraInfo(sensor_msgs.srv.SetCameraInfo_Request req);
            (L____________, std_srvs.srv.Empty_Response) std_srvs_Empty(std_srvs.srv.Empty_Request req);
            (L____________, std_srvs.srv.SetBool_Response) std_srvs_SetBool(std_srvs.srv.SetBool_Request req);
            (L____________, std_srvs.srv.Trigger_Response) std_srvs_Trigger(std_srvs.srv.Trigger_Request req);
            (L____________, test_msgs.srv.Arrays_Response) test_msgs_Arrays(test_msgs.srv.Arrays_Request req);
            (L____________, test_msgs.srv.BasicTypes_Response) test_msgs_BasicTypes(test_msgs.srv.BasicTypes_Request req);
            (L____________, test_msgs.srv.Empty_Response) test_msgs_Empty(test_msgs.srv.Empty_Request req);
            (L____________, type_description_interfaces.srv.GetTypeDescription_Response) type_description_interfaces_GetTypeDescription(type_description_interfaces.srv.GetTypeDescription_Request req);
            (L____________, visualization_msgs.srv.GetInteractiveMarkers_Response) visualization_msgs_GetInteractiveMarkers(visualization_msgs.srv.GetInteractiveMarkers_Request req);

            // Action example_interfaces/Fibonacci: goal → feedback stream → result. Several goals may be in flight at once.
            interface example_interfaces_Fibonacci : Actor {
                int MaxActiveInstances => UNLIMITED;

                [L____________<Executing, example_interfaces.action.Fibonacci_Goal>]
                struct SendGoal { }

                [____________r<example_interfaces.action.Fibonacci_Feedback>]
                [l____________<action_msgs.srv.CancelGoal_Request>]
                [____________R<End, example_interfaces.action.Fibonacci_Result>]
                struct Executing { }
            }

            // Action test_msgs/Fibonacci: goal → feedback stream → result. Several goals may be in flight at once.
            interface test_msgs_Fibonacci : Actor {
                int MaxActiveInstances => UNLIMITED;

                [L____________<Executing, test_msgs.action.Fibonacci_Goal>]
                struct SendGoal { }

                [____________r<test_msgs.action.Fibonacci_Feedback>]
                [l____________<action_msgs.srv.CancelGoal_Request>]
                [____________R<End, test_msgs.action.Fibonacci_Result>]
                struct Executing { }
            }

            // Action test_msgs/NestedMessage: goal → feedback stream → result. Several goals may be in flight at once.
            interface test_msgs_NestedMessage : Actor {
                int MaxActiveInstances => UNLIMITED;

                [L____________<Executing, test_msgs.action.NestedMessage_Goal>]
                struct SendGoal { }

                [____________r<test_msgs.action.NestedMessage_Feedback>]
                [l____________<action_msgs.srv.CancelGoal_Request>]
                [____________R<End, test_msgs.action.NestedMessage_Result>]
                struct Executing { }
            }
        }

        // ═════════════════════════ ROS 2 metadata attributes ═════════════════════════

        // Custom attribute: carried into the generated code as a constant attached to the field.
        // Declared inside the project interface (the agent expects every class in a project);
        // the Topics branch selects packs by `.msg.` so this class is never collected.
        /** Field default value, as written in the ROS interface file. */
        public class DefaultAttribute : Attribute { public DefaultAttribute(string value) { } }

    }
